39	// diff marks it as a promote run, so CI keys on its branch prefix — but a
40	// capture run marks ITSELF via its title, so this rule self-gates and runs
41	// everywhere the pack is active: at the session Stop hook (work scope), and as
42	// a CLI on every PR in the canon repo's CI.
43	//
44	// Local packs live under either root during the rename transition; git emits
45	// '/'-separated paths, so the platform-joined constants are normalized.
46	const LOCAL_ROOTS = [LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR]
47	  .map((s) => `${s.split(sep).join('/')}/`);
48	
49	// The capture runs, by the exact titles their task docs pin. `conversation
50	// extract` is the pre-merge title of extract's conversation half, still in use
51	// wherever a consumer mounts a canon older than the one-task merge.
52	const CAPTURE_RUN = /^Claudinite growth: (?:extract lessons|conversation extract|dedup\b)/;
53	
54	const inSurface = (p) => LOCAL_ROOTS.some((root) => p.startsWith(root));
55	
56	const rule = {
57	  id: 'growth-write-scope',
58	  severity: 'blocking',
59	  scope: 'work',
60	  doc: 'packs/claudinite-growth/README.md',
61	  description: 'A growth capture run (extract, dedup) writes only the repo\'s own local packs, plus comment-only edits at the call sites its lessons are about',
62	  why: 'extract auto-merges its PR with no human review and dedup runs unattended; a capture run improves the repo\'s packs and the comments at the call sites its lessons are about, so any other write outside .claudinite/local/packs/ — the canon it prunes against, or the project\'s own logic — escapes the review-by-blast-radius boundary the growth lifecycle is built on',
63	
64	  run(work) {
65	    if (work.onDefaultBranch()) return [];
66	    if (!work.commits.some((m) => CAPTURE_RUN.test(m))) return [];
67	    const touched = [...new Set([...work.changedFiles, ...work.deleted])];
68	    return touched
69	      .filter((p) => !inSurface(p))
70	      .filter((p) => !commentOnly(p, work.readBase(p), work.read(p)))
71	      .sort()
72	      .map((p) => finding(rule, {
73	        file: p,
74	        what: `a growth capture run touched ${p}, outside ${LOCAL_ROOTS[0]}, and not only its comments`,
75	        fix: 'a capture run improves the repo\'s packs and may correct or delete a comment at a call site a lesson is about — nothing else out there; keep every other write inside the local packs, and leave lifting a lesson into the canon to the promote stage',
76	      }));
77	  },
78	};
79	
80	export default rule;
81	
82	// CLI body — a CI gate runs this on every PR (self-gating, ~nothing on a
83	// branch that is not a capture run). In the canon repo the entrypoint is
84	// canon-curation's growth-scope-gate.mjs (core CI must not name a specific
85	// pack — the barriers rule); a consumer wiring its own CI would invoke this
86	// module directly:
87	// `node .claudinite/shared/packs/claudinite-growth/workRules/growth-write-scope.mjs [root]`.
88	//   exit 0 — not a capture run, or every touched path is under the local packs
89	//   exit 1 — a capture run touched a path outside the local packs
90	export function runCli(root = process.cwd()) {
91	  const ctx = buildContext({ root, mode: 'changed' });
92	  if (!ctx.mergeBase) {
93	    // Without a merge-base there is no diff — and no branch commits — to read,
94	    // so there is nothing to self-gate on. Unlike promote-scope (whose CI step
95	    // already KNOWS it faces a promote PR), refusing here would fail every
96	    // history-less checkout on ordinary PRs; the Stop-hook run still covers
97	    // the session side.
98	    console.log('growth-write-scope: no merge-base with the base branch — nothing to scope.');
99	    process.exit(0);
100	  }
101	  const findings = runRule(rule, ctx);
102	  if (findings.length) {
103	    console.error(`growth-write-scope: FAIL — a growth capture run may write only under ${LOCAL_ROOTS[0]} plus comment-only edits elsewhere, but this branch also changes ${findings.length} path(s):`);
104	    for (const f of findings) console.error(`  - ${f.file}`);
105	    console.error('\nA capture run improves the repo\'s packs and may correct or delete a comment at a call site — nothing else out there.');
106	    process.exit(1);
107	  }
108	  console.log('growth-write-scope: OK — not a capture run, or every touched path is under the local packs or comment-only.');
109	}
110	
111	if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
112	  runCli(process.argv[2] || process.cwd());
113	}

